# Query to prepare data so the migration can be validated
TWO_BAD_DELETE_VISITS = """
        MATCH (sv:StudyValue)-[sv_ss]-(ss)-[ss_sa:AFTER]-(sa:StudyAction)<-[:AUDIT_TRAIL]-(sr:StudyRoot) 
        WHERE 
        not exists((sa)-[:BEFORE]-()) 
        AND (ss:StudyVisit )
        WITH *
        LIMIT 2
        // DISCONNECT OLD NODE
        DELETE sv_ss
        //CREATE EXTRA NODES FOR NEW NODE
        CREATE (new_sa:StudyAction:Delete{status:"DRAFT", date: datetime({epochMillis: apoc.date.currentTimestamp()}) , user_initials:"Unkown-User"})-[:BEFORE]->(ss)
        //CONNECT OLD NODE
        CREATE (sr)-[:AUDIT_TRAIL]->(new_sa);
        """

# Query to prepare data so the migration can be validated
ONE_BAD_DELETE_EPOCH = """
        WITH NULL as null
        MATCH (sv_2:StudyValue)-[sv_ss_2]-(ss)-[ss_sa_2:AFTER]-(sa_2:StudyAction)<-[:AUDIT_TRAIL]-(sr_2:StudyRoot) 
            WHERE 
                not exists((sa_2)-[:BEFORE]-()) AND 
                (ss:StudyEpoch) AND
                NOT EXISTS((ss)--(:StudyVisit)--(:StudyValue)) //BE SURE THAT THERE'S NO VISIT ALIVE CONNECTED TO IT 
        WITH *
        LIMIT 1
        // DISCONNECT OLD NODE
        DELETE sv_ss_2
        //CREATE EXTRA NODES FOR NEW NODE
        CREATE (new_sa_2:StudyAction:Delete{status:"DRAFT", date: datetime({epochMillis: apoc.date.currentTimestamp()}) , user_initials:"Unkown-User"})-[:BEFORE]->(ss)
        //CONNECT OLD NODE
        CREATE (sr_2)-[:AUDIT_TRAIL]->(new_sa_2);
        """

